#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>
Adafruit_PWMServoDriver pwm = Adafruit_PWMServoDriver(0x40);
void setup() {
  pwm.begin();
  pwm.setPWMFreq(50); // 50Hz for standard RC servos
}
void loop() {
  pwm.setPWM(0, 0, 375); // Center channel 0 servo at ~90 deg
  delay(1000);
}
